def get_kth_char(s: str, k: int) -> str:
    n = len(s)
    # Forward: calculate length after each op
    lens = [0] * (n + 1)
    for i in range(n):
        c = s[i]
        if 'a' <= c <= 'z':
            lens[i+1] = lens[i] + 1
        elif c == '*':
            lens[i+1] = max(0, lens[i] - 1)
        elif c == '#':
            lens[i+1] = lens[i] * 2
        elif c == '%':
            lens[i+1] = lens[i]
    # If k > length, return '.'
    if k > lens[n] or k < 1:
        return '.'
    # Backward: trace back k
    for i in range(n, 0, -1):
        c = s[i-1]
        if 'a' <= c <= 'z':
            if lens[i] == lens[i-1] + 1:
                if k == lens[i]:
                    return c
                # else: k remains
        elif c == '*':
            if lens[i] == lens[i-1] - 1:
                # a char has been popped
                if k == lens[i-1]:
                    # would have been the last char
                    return '.'
                # else k remains
        elif c == '#':
            if k > lens[i] // 2:
                k -= lens[i] // 2
            # else: k stays
        elif c == '%':
            k = lens[i] - k + 1
    return '.'
